package com.fream.back.domain.m53.entity;

import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.global.entity.Xzh80Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Table(
        indexes = {
                @Index(name = "idx_user_id", columnList = "user_id"),
                @Index(name = "idx_is_default", columnList = "is_default")
        }
)
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xms98 extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xjm45 user;

    @Column(nullable = false)
    private String recipientName;

    @Column(nullable = false)
    private String phoneNumber;

    @Column(nullable = false)
    private String zipCode;

    @Column(nullable = false)
    private String address;

    private String detailedAddress;

    @Column(name = "is_default")
    private boolean isDefault;


    public void updateAddress(String recipientName, String phoneNumber, String zipCode,
                              String address, String detailedAddress, Boolean isDefault) {
        if (recipientName != null) {
            this.recipientName = recipientName;
        }
        if (phoneNumber != null) {
            this.phoneNumber = phoneNumber;
        }
        if (zipCode != null) {
            this.zipCode = zipCode;
        }
        if (address != null) {
            this.address = address;
        }
        if (detailedAddress != null) {
            this.detailedAddress = detailedAddress;
        }
        if (isDefault != null) {
            this.isDefault = isDefault;
        }
    }


    public void assignUser(Xjm45 user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }
}package com.fream.back.domain.m53.service.command;

import com.fream.back.domain.m53.dto.Xms98CreateDto;
import com.fream.back.domain.m53.dto.Xms98UpdateDto;
import com.fream.back.domain.m53.entity.Xms98;
import com.fream.back.domain.m53.exception.Xms98ErrorCode;
import com.fream.back.domain.m53.exception.Xms98Exception;
import com.fream.back.domain.m53.exception.Xpp56Exception;
import com.fream.back.domain.m53.exception.Xkk16Exception;
import com.fream.back.domain.m53.repository.Xms98Repository;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.repository.Xjm45Repository;
import com.fream.back.global.utils.Xhr91Util;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class Xms98CommandService {

    private final Xjm45Repository userRepository;
    private final Xms98Repository addressRepository;
    private final Xhr91Util encryptionUtil;


    @Transactional
    public void createAddress(String email, Xms98CreateDto createDto) {
        try {
            Xjm45 user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 생성 시작: 사용자={}, 수신자={}", email, createDto.getRecipientName());

            if (createDto.getIsDefault() != null && createDto.getIsDefault()) {

                log.debug("기존 기본 주소 해제: 사용자={}", email);
                user.getAddresses().forEach(address -> address.updateAddress(
                        null, null, null, null, null, false));
            }



            String encryptedRecipientName = encryptionUtil.deterministicEncrypt(createDto.getRecipientName());
            String encryptedPhoneNumber = encryptionUtil.deterministicEncrypt(createDto.getPhoneNumber());
            String encryptedZipCode = encryptionUtil.deterministicEncrypt(createDto.getZipCode());
            String encryptedAddress = encryptionUtil.deterministicEncrypt(createDto.getAddress());


            String encryptedDetailedAddress = createDto.getDetailedAddress() != null ?
                    encryptionUtil.encrypt(createDto.getDetailedAddress()) : null;

            Xms98 newAddress = Xms98.builder()
                    .user(user)
                    .recipientName(encryptedRecipientName)
                    .phoneNumber(encryptedPhoneNumber)
                    .zipCode(encryptedZipCode)
                    .address(encryptedAddress)
                    .detailedAddress(encryptedDetailedAddress)
                    .isDefault(createDto.getIsDefault() != null && createDto.getIsDefault())
                    .build();

            addressRepository.save(newAddress);
            log.info("주소 생성 완료: 사용자={}, 주소ID={}", email, newAddress.getId());
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("주소 생성 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_CREATE_ERROR, e);
        }
    }


    @Transactional
    public void updateAddress(String email, Xms98UpdateDto updateDto) {
        try {
            Xjm45 user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new Xkk16Exception(
