package com.fream.back.domain.m53.service.query;

import com.fream.back.domain.m53.dto.Xms98ResponseDto;
import com.fream.back.domain.m53.entity.Xms98;
import com.fream.back.domain.m53.exception.Xms98ErrorCode;
import com.fream.back.domain.m53.exception.Xms98Exception;
import com.fream.back.domain.m53.exception.Xpp56Exception;
import com.fream.back.domain.m53.exception.Xkk16Exception;
import com.fream.back.domain.m53.repository.Xms98Repository;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.repository.Xjm45Repository;
import com.fream.back.global.utils.Xhr91Util;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class Xms98QueryService {

    private final Xjm45Repository userRepository;
    private final Xms98Repository addressRepository;
    private final Xhr91Util encryptionUtil;


    @Transactional(readOnly = true)
    public List<Xms98ResponseDto> getAddresses(String email) {
        try {
            log.info("주소 목록 조회 시작: 사용자={}", email);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xjm45 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            List<Xms98ResponseDto> addresses = user.getAddresses().stream()
                    .map(address -> new Xms98ResponseDto(
                            address.getId(),

                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),

                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("주소 목록 조회 완료: 사용자={}, 조회된 주소 수={}", email, addresses.size());
            return addresses;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("주소 목록 조회 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }


    @Transactional(readOnly = true)
    public Xms98ResponseDto getAddress(String email, Long addressId) {
        try {
            log.info("단일 주소 조회 시작: 사용자={}, 주소ID={}", email, addressId);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xjm45 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            Xms98 address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new Xpp56Exception(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));


            Xms98ResponseDto responseDto = new Xms98ResponseDto(
                    address.getId(),

                    encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                    encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                    encryptionUtil.deterministicDecrypt(address.getZipCode()),
                    encryptionUtil.deterministicDecrypt(address.getAddress()),

                    address.getDetailedAddress() != null ?
                            encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                    address.isDefault()
            );

            log.info("단일 주소 조회 완료: 사용자={}, 주소ID={}", email, addressId);
            return responseDto;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("단일 주소 조회 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }




    @Transactional(readOnly = true)
    public List<Xms98ResponseDto> searchAddressesByRecipientName(String email, String recipientName) {
        try {
            log.info("이름으로 주소 검색 시작: 사용자={}, 검색어={}", email, recipientName);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xjm45 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));


            String encryptedSearchTerm = encryptionUtil.encryptForSearch(recipientName);


            List<Xms98> foundAddresses = addressRepository.findByUserAndRecipientName(user, encryptedSearchTerm);

            List<Xms98ResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new Xms98ResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("이름으로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, recipientName, addresses.size());
            return addresses;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("이름으로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, recipientName, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }




    @Transactional(readOnly = true)
    public List<Xms98ResponseDto> searchAddressesByPhoneNumber(String email, String phoneNumber) {
        try {
            log.info("전화번호로 주소 검색 시작: 사용자={}, 검색어={}", email, phoneNumber);


            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            Xjm45 user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));


            String encryptedSearchTerm = encryptionUtil.encryptForSearch(phoneNumber);


            List<Xms98> foundAddresses = addressRepository.findByUserAndPhoneNumber(user, encryptedSearchTerm);

            List<Xms98ResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new Xms98ResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("전화번호로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, phoneNumber, addresses.size());
            return addresses;
        } catch (Xms98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("전화번호로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, phoneNumber, e.getMessage(), e);
            throw new Xms98Exception(Xms98ErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }
}package com.fream.back.global.utils;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;






@Slf4j
@Component
@RequiredArgsConstructor
public class Xhr91Util {

    @Value("${personal-data.encryption.secret-key}")
    private String secretKey;

    @Value("${personal-data.encryption.iv}")
    private String iv;

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final String DETERMINISTIC_ALGORITHM = "AES/ECB/PKCS5Padding";








    public String encrypt(String plainText) {
        if (plainText == null || plainText.isEmpty()) {
            return plainText;
        }

        try {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), "AES");
            IvParameterSpec ivParamSpec = new IvParameterSpec(iv.getBytes(StandardCharsets.UTF_8));

            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivParamSpec);
            byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

            return Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception e) {
            log.error("데이터 암호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("데이터 암호화 처리 중 오류가 발생했습니다", e);
        }
    }







    public String decrypt(String encryptedText) {
        if (encryptedText == null || encryptedText.isEmpty()) {
            return encryptedText;
        }

        try {
